
create table app_user(username varchar(50) primary key, password varchar(100) not null, role varchar(30) not null);
create table specification(reference varchar(40) primary key, material_type varchar(20) not null, test_name varchar(60) not null, unit varchar(30) not null, minimum numeric not null, maximum numeric not null, rule_version varchar(20) not null);
create table purchase_order(code varchar(40) primary key, supplier varchar(100) not null, reference varchar(40) references specification(reference), expected_quantity numeric(14,3) not null check(expected_quantity>0));
create table lot(id uuid primary key, order_code varchar(40) not null references purchase_order(code), supplier_lot varchar(80) not null, production_date date not null, quantity numeric(14,3) not null check(quantity>0), location varchar(100) not null, quality_state varchar(30) not null check(quality_state in ('UNDER_VERIFICATION','UNDER_TEST','HELD','RELEASED')), inventory_state varchar(30) not null check(inventory_state in ('QUARANTINE','BLOCKED','AVAILABLE')), version bigint not null default 0, cycle integer not null default 0, sample_code varchar(80), result_value numeric, tested_by varchar(50) references app_user(username), created_at timestamptz not null default now(), unique(order_code,supplier_lot), check(inventory_state <> 'AVAILABLE' or quality_state='RELEASED'));
create table audit_event(id uuid primary key, lot_id uuid references lot(id), actor varchar(50) not null references app_user(username), role varchar(30) not null, event_type varchar(50) not null, from_state varchar(80), to_state varchar(80), reason text not null, evidence text not null, rule_version varchar(20) not null, correlation_id uuid not null, payload text not null, occurred_at timestamptz not null default now());
create table command_result(actor varchar(50) references app_user(username), command_key uuid not null, fingerprint text not null, lot_id uuid not null references lot(id), primary key(actor,command_key));
create function prevent_audit_change() returns trigger language plpgsql as $$ begin raise exception 'Audit events are append-only'; end $$;
create trigger audit_immutable before update or delete on audit_event for each row execute function prevent_audit_change();
